import { Node } from './Node.js';
export class Scene extends Node {
    nodes = new Map();
    nextNodeNumber = 1;
    autoDisposeResources;
    constructor(options = {}) {
        super({ ...options, id: options.id ?? 'scene', name: options.name ?? 'Scene' });
        this.autoDisposeResources = options.autoDisposeResources ?? true;
        this.attachRegistry(this);
    }
    get(id) { return this.nodes.get(id); }
    require(id) {
        const node = this.get(id);
        if (!node)
            throw new Error(`Scene node not found: ${id}`);
        return node;
    }
    findByTag(tag) {
        const matches = [];
        for (const node of this.nodes.values())
            if (node.hasTag(tag))
                matches.push(node);
        return matches;
    }
    register(node) {
        if (!node.id)
            node.assignId(`node-${this.nextNodeNumber++}`);
        const existing = this.nodes.get(node.id);
        if (existing && existing !== node)
            throw new Error(`Duplicate scene node ID: ${node.id}`);
        this.nodes.set(node.id, node);
    }
    unregister(node) {
        if (this.nodes.get(node.id) === node)
            this.nodes.delete(node.id);
    }
    clone(recursive = true) {
        const copy = new Scene({ id: this.id, name: this.name, tags: [...this.tags], visible: this.visible, layerMask: this.layerMask, autoDisposeResources: this.autoDisposeResources });
        copy.position.copy(this.position);
        copy.rotation.copy(this.rotation);
        copy.scale.copy(this.scale);
        if (recursive)
            for (const child of this.children)
                copy.add(child.clone(true));
        return copy;
    }
}
export function createScene(options) { return new Scene(options); }